using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.SignalR;
using System.Text.Json;
namespace Society.Api;
public class MailWorker(IServiceScopeFactory factory,IConfiguration config,IHostEnvironment env,ILogger<MailWorker> log,IHubContext<CommunicationHub> hub):BackgroundService {
 protected override async Task ExecuteAsync(CancellationToken stop){var sweep=DateTimeOffset.MinValue;var retention=DateTimeOffset.MinValue;while(!stop.IsCancellationRequested){var worked=false;try{using var scope=factory.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();await CampaignBatch(db,stop);if(sweep<DateTimeOffset.UtcNow){await AutomationBatch(db,stop);await SystemNotifications(db,stop);if(retention<DateTimeOffset.UtcNow){await Retention(db,stop);retention=DateTimeOffset.UtcNow.AddHours(1);}sweep=DateTimeOffset.UtcNow.AddSeconds(1);}var job=await Claim(db,stop);if(job!=null){worked=true;await Dispatch(db,scope.ServiceProvider,job,stop);}}catch(Exception ex)when(!stop.IsCancellationRequested){log.LogWarning("Communication worker failed: {Type}",ex.GetType().Name);}if(!worked)try{await Task.Delay(250,stop);}catch(OperationCanceledException){break;}}}
 async Task Retention(AppDb db,CancellationToken ct){foreach(var policy in await db.Set<CommunicationPolicy>().AsNoTracking().ToListAsync(ct)){var cutoff=DateTimeOffset.UtcNow.AddDays(-policy.RetentionDays);await db.Set<CommunicationMessage>().Where(m=>m.TenantId==policy.TenantId&&m.At<cutoff&&m.RemovedAt==null).ExecuteUpdateAsync(x=>x.SetProperty(m=>m.Body,"[Removed under retention policy]").SetProperty(m=>m.RemovedAt,DateTimeOffset.UtcNow),ct);await db.Set<CommunicationNotification>().Where(n=>n.TenantId==policy.TenantId&&n.At<cutoff).ExecuteDeleteAsync(ct);await db.Outbox.Where(o=>o.TenantId==policy.TenantId&&o.CreatedAt<cutoff&&!new[]{"Queued","Held","Retry","Processing"}.Contains(o.Status)&&o.Body!="[Removed under retention policy]").ExecuteUpdateAsync(x=>x.SetProperty(o=>o.Body,"[Removed under retention policy]"),ct);}}
 public static async Task<bool> Authority(AppDb db,Guid tenant,Guid user,Guid? unit,string permission){var now=DateTimeOffset.UtcNow;if(!await db.Links.AnyAsync(l=>l.TenantId==tenant&&l.UserId==user&&db.Tenants.Any(t=>t.Id==tenant&&t.Status=="Active")))return false;if(unit!=null)return await Access.UnitsFor(db,tenant,user,permission).AnyAsync(u=>u.Id==unit);return await db.Assignments.AnyAsync(ass=>ass.TenantId==tenant&&ass.UserId==user&&ass.UnitId==null&&ass.RevokedAt==null&&ass.StartsAt<=now&&(ass.EndsAt==null||ass.EndsAt>now)&&(ass.MembershipId==null||db.Memberships.Any(m=>m.Id==ass.MembershipId&&m.Status=="Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now)))&&db.GovernanceRoles.Any(r=>r.Id==ass.RoleId&&r.Permissions.Contains(permission)));}
 async Task<Outbox?> Claim(AppDb db,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);var now=DateTimeOffset.UtcNow;var items=await db.Outbox.FromSqlInterpolated($"SELECT * FROM \"Outbox\" WHERE \"SentAt\" IS NULL AND ((\"Status\" IN ('Queued','Retry') AND \"NextAttemptAt\"<={now}) OR (\"Status\"='Processing' AND \"LeaseUntil\"<{now})) ORDER BY \"NextAttemptAt\",\"CreatedAt\" LIMIT 1 FOR UPDATE SKIP LOCKED").ToListAsync(ct);var job=items.FirstOrDefault();if(job!=null){if(job.Status=="Processing"&&job.Channel!="InApp"){job.Status="Unknown";job.Error="Worker lease expired with uncertain transport outcome; reconcile before retry";job.LeaseUntil=null;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return null;}job.Status="Processing";job.LeaseOwner=Guid.NewGuid().ToString();job.LeaseUntil=now.AddMinutes(2);await db.SaveChangesAsync(ct);}await tx.CommitAsync(ct);return job;}
 async Task CampaignBatch(AppDb db,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);var now=DateTimeOffset.UtcNow;var list=await db.Set<CommunicationCampaign>().FromSqlInterpolated($"SELECT * FROM \"CommunicationCampaign\" WHERE \"Status\" IN ('Scheduled','Dispatching') AND \"ScheduledAt\"<={now} ORDER BY \"ScheduledAt\" LIMIT 1 FOR UPDATE SKIP LOCKED").ToListAsync(ct);var c=list.FirstOrDefault();if(c==null){await tx.CommitAsync(ct);return;}if(c.Kind=="Announcement"&&c.EnqueuedCount==0&&!await db.Audits.AnyAsync(a=>a.TenantId==c.TenantId&&a.ResourceId==c.Id&&a.Action=="communication.announcement.published",ct))db.Add(new Audit{TenantId=c.TenantId,ActorId=c.AuthorId,Action="communication.announcement.published",ResourceId=c.Id});if(c.ExpiresAt<=now||!await Authority(db,c.TenantId,c.AuthorId,c.UnitId,"communications.send")){c.Status="Cancelled";await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return;}var rows=await db.Set<CampaignRecipient>().Where(r=>r.CampaignId==c.Id&&r.SnapshotVersion==c.SnapshotVersion&&r.Status=="Pending").OrderBy(r=>r.Id).Take(200).ToListAsync(ct);foreach(var r in rows){var vars=JsonSerializer.Deserialize<Dictionary<string,string>>(r.Variables)!;var token=CommunityService.Token();var body=CommunicationService.Render(c.Body,vars);if(c.Channel=="Email")body+="\nManage communication preferences: "+(config["PublicUrl"]??"").TrimEnd('/')+"/unsubscribe?token="+token;var job=new Outbox{SenderId=c.AuthorId,TenantId=c.TenantId,UnitId=c.UnitId,UserId=r.UserId,MembershipId=r.MembershipId,CampaignId=c.Id,AccountId=c.AccountId,Channel=c.Channel,Recipient=r.Destination,Subject=CommunicationService.Render(c.Subject,vars),Body=body,IdempotencyKey="campaign:"+c.Id+":"+r.PersonId,UnsubscribeHash=CommunityService.Hash(token)};if(c.TemplateId!=null){var template=await db.Set<CommunicationTemplate>().FindAsync([c.TemplateId],ct);if(c.Channel=="WhatsApp"){if(template?.ProviderStatus!="APPROVED"||template.ProviderAccountId!=c.AccountId){r.Status="Suppressed";continue;}job.TemplateName=template.ProviderName;job.TemplateLanguage=template.Language;job.TemplateParameters=JsonSerializer.Serialize(MetaTemplates.Parameters(template,vars));}}db.Outbox.Add(job);r.OutboxId=job.Id;r.Status="Queued";c.EnqueuedCount++;}c.Status=rows.Count<200?"Enqueued":"Dispatching";await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}
 async Task Dispatch(AppDb db,IServiceProvider services,Outbox job,CancellationToken ct){var now=DateTimeOffset.UtcNow;var result=new DispatchResult("Failed");var account=job.AccountId==null?null:await db.Set<CommunicationAccount>().FindAsync([job.AccountId],ct);
 if(job.IdempotencyKey?.StartsWith("membership-renewal:")==true&&job.AccountId==null&&job.SenderId==null&&job.Channel=="Email"&&job.TenantId!=null&&job.MembershipId!=null&&job.UserId!=null){var parts=job.IdempotencyKey.Split(':');var validKey=parts.Length==3&&Guid.TryParse(parts[1],out var noticeId)&&parts[2]==job.UserId.Value.ToString();var notice=validKey?await db.Set<MembershipRenewalNotice>().SingleOrDefaultAsync(n=>n.Id==Guid.Parse(parts[1])&&n.TenantId==job.TenantId&&n.MembershipId==job.MembershipId,ct):null;var member=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==job.TenantId&&m.Id==job.MembershipId,ct);if(notice==null||member==null||!member.RenewalReminders||member.Status!="Active"||member.PendingPayment||member.EndsAt!=notice.TermEnd||!await db.Tenants.AnyAsync(t=>t.Id==job.TenantId&&t.Status=="Active",ct)||!await MembershipExperience.Owned(db,job.UserId.Value,true).AnyAsync(m=>m.Id==job.MembershipId,ct)||!await db.Users.AnyAsync(u=>u.Id==job.UserId&&u.EmailConfirmed&&u.Email==job.Recipient,ct)){await Finish(db,job,new("Suppressed",Error:"Renewal reminder consent, recipient or term changed"),ct);return;}var sent=await SystemEmail(db,job,ct);if(sent!=null)await Finish(db,job,sent,ct);return;}
 if(job.TenantId!=null){var tenant=job.TenantId.Value;if(!await db.Tenants.AnyAsync(t=>t.Id==tenant&&t.Status=="Active",ct)){await Finish(db,job,new("Suppressed",Error:"Society is inactive"),ct);return;}if(job.FinanceInvoiceId!=null){var invoice=await db.Set<FinanceInvoice>().AsNoTracking().SingleOrDefaultAsync(i=>i.TenantId==tenant&&i.Id==job.FinanceInvoiceId,ct);if(invoice==null||invoice.BilledUnitId!=null&&(job.UserId==null||!await Authority(db,tenant,job.UserId.Value,invoice.UnitId,"finance.read"))){await Finish(db,job,new("Suppressed",Error:"Current financial recipient authority is insufficient"),ct);return;}}if(job.IdempotencyKey!=null&&job.IdempotencyKey.StartsWith("finance-review:")&&(job.UserId==null||!await Authority(db,tenant,job.UserId.Value,job.UnitId,"finance.approve"))){await Finish(db,job,new("Suppressed",Error:"Reviewer authority expired"),ct);return;}if(job.SenderId!=null&&(!await Authority(db,tenant,job.SenderId.Value,job.UnitId,"communications.send")||job.IdempotencyKey!=null&&job.IdempotencyKey.StartsWith("finance-")&&!await Authority(db,tenant,job.SenderId.Value,job.UnitId,"finance.collect"))){await Finish(db,job,new("Suppressed",Error:"Sender authority expired"),ct);return;}if(job.MembershipId!=null){var m=await db.Memberships.AsNoTracking().SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==job.MembershipId,ct);var pref=job.UserId==null?new CommunicationPreference():await db.Set<CommunicationPreference>().AsNoTracking().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.UserId==job.UserId,ct)??new();if(m==null||m.Status!="Active"||m.EffectiveFrom>now||m.EndsAt<=now||!CommunityService.CommunicationAllowed(m.Privacy)||!CommunicationService.ChannelAllowed(pref,job.Channel)||await db.Set<CommunicationSuppression>().AnyAsync(s=>s.TenantId==tenant&&s.Channel==job.Channel&&s.DestinationHash==CommunityService.Hash(job.Recipient.ToLowerInvariant()),ct)){await Finish(db,job,new("Suppressed",Error:"Current consent, eligibility or suppression prevents dispatch"),ct);return;}var profile=MembershipService.Json(m.Profile);var destination=job.Channel=="InApp"?job.UserId?.ToString()??"":job.Channel=="Email"?(job.UserId==null?profile["email"]?.ToString()??"":await db.Users.Where(u=>u.Id==job.UserId).Select(u=>u.Email).SingleAsync(ct)??""):profile["phone"]?.ToString()??"";if(!string.Equals(destination,job.Recipient,StringComparison.OrdinalIgnoreCase)){await Finish(db,job,new("Suppressed",Error:"Recipient contact changed after the snapshot"),ct);return;}if(job.CampaignId!=null){var c=await db.Set<CommunicationCampaign>().AsNoTracking().SingleAsync(c=>c.Id==job.CampaignId,ct);if(c.Status=="Cancelled"||c.ExpiresAt<=now||c.SnapshotCount>(await db.Set<CommunicationPolicy>().SingleAsync(p=>p.TenantId==tenant,ct)).HighVolumeThreshold&&!await Authority(db,tenant,c.AuthorId,c.UnitId,"communications.highvolume")||!await Authority(db,tenant,c.AuthorId,m.ChapterId,"communications.send")){await Finish(db,job,new("Cancelled",Error:"Campaign or sender authority is no longer valid"),ct);return;}}var quiet=CommunicationService.QuietUntil(pref,now);if(quiet>now){job.Status="Queued";job.NextAttemptAt=quiet;job.LeaseUntil=null;await db.SaveChangesAsync(ct);return;}}
 if(job.Channel=="InApp"){if(job.UserId==null){await Finish(db,job,new("Failed",Error:"No verified in-app account"),ct);return;}var campaign=job.CampaignId==null?null:await db.Set<CommunicationCampaign>().AsNoTracking().SingleAsync(c=>c.Id==job.CampaignId,ct);if(!await db.Set<CommunicationNotification>().AnyAsync(n=>n.TenantId==tenant&&n.UserId==job.UserId&&n.DedupKey=="outbox:"+job.Id,ct))db.Add(new CommunicationNotification{TenantId=tenant,UserId=job.UserId.Value,Title=job.Subject,Kind=campaign?.Kind??"Message",Link=campaign==null?(job.IdempotencyKey!=null&&job.IdempotencyKey.StartsWith("finance-")?(job.IdempotencyKey.StartsWith("finance-review:")?"/app/finance/expenses":job.IdempotencyKey.StartsWith("finance-chapter:")?"/app/finance/chapter-dues":"/app/finance/my"):"/app/communications"):"/app/communications/received/"+campaign.Id,ResourceId=campaign?.Id??job.Id,DedupKey="outbox:"+job.Id});job.Attempts++;await Finish(db,job,new("Delivered","internal:"+job.Id),ct);await hub.Clients.Group("user:"+job.UserId).SendAsync("changed",new{kind="notification"},ct);return;}
 if(account==null||account.TenantId!=tenant||account.Channel!=job.Channel||account.UnitId!=null&&account.UnitId!=job.UnitId||!account.Enabled||!account.Verified){await Finish(db,job,new("Unavailable",Error:"Configure and verify a sending account before dispatch"),ct);return;}
 if(job.Channel=="WhatsApp"&&job.TemplateName==null&&!await db.Set<CommunicationMessage>().AnyAsync(m=>m.TenantId==tenant&&m.ConversationId==job.ConversationId&&m.Direction=="Incoming"&&m.At>=now.AddHours(-24),ct)){await Finish(db,job,new("Failed",Error:"WhatsApp free-form service window is closed"),ct);return;}
 await using(var rate=await db.Database.BeginTransactionAsync(ct)){var locked=await db.Set<CommunicationAccount>().FromSqlInterpolated($"SELECT * FROM \"CommunicationAccount\" WHERE \"Id\"={account.Id} FOR UPDATE").ToListAsync(ct);var sender=locked.Single();if(sender.WindowStart.AddMinutes(1)<=now){sender.WindowStart=now;sender.WindowCount=0;}if(sender.WindowCount>=sender.PerMinute){job.Status="Retry";job.NextAttemptAt=sender.WindowStart.AddMinutes(1);job.LeaseUntil=null;await db.SaveChangesAsync(ct);await rate.CommitAsync(ct);return;}sender.WindowCount++;await db.SaveChangesAsync(ct);await rate.CommitAsync(ct);}
 job.Attempts++;var provider=services.GetRequiredService<CommunicationProviders>();result=await provider.Send(job,account,provider.Secrets(account),ct);
 }else{var sent=await SystemEmail(db,job,ct);if(sent==null)return;result=sent;}
 await Finish(db,job,result,ct);
 }
 async Task<DispatchResult?> SystemEmail(AppDb db,Outbox job,CancellationToken ct){if(!env.IsDevelopment()&&string.IsNullOrWhiteSpace(config["Smtp:Host"])){job.Status="Queued";job.NextAttemptAt=DateTimeOffset.UtcNow.AddMinutes(5);job.LeaseUntil=null;job.Error="Email delivery is awaiting SMTP configuration";await db.SaveChangesAsync(ct);return null;}job.Attempts++;try{if(env.IsDevelopment()&&string.IsNullOrEmpty(config["Smtp:Host"])){var dir=Path.GetFullPath(Path.Combine(env.ContentRootPath,"../.local/mail"));Directory.CreateDirectory(dir);await File.WriteAllTextAsync(Path.Combine(dir,job.Id+".json"),JsonSerializer.Serialize(new{job.Recipient,job.Subject,job.Body}),ct);return new("Pickup","pickup:"+job.Id);}using var smtp=new System.Net.Mail.SmtpClient(config["Smtp:Host"],config.GetValue("Smtp:Port",587)){EnableSsl=true,Credentials=new System.Net.NetworkCredential(config["Smtp:User"],config["Smtp:Password"]),Timeout=20000};using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(20));await smtp.SendMailAsync(new System.Net.Mail.MailMessage(config["Smtp:From"]!,job.Recipient,job.Subject,job.Body),timeout.Token);return new("Accepted","smtp:"+job.Id);}catch{return new("Unknown",Error:"SMTP transport outcome requires reconciliation");}}
 async Task Finish(AppDb db,Outbox job,DispatchResult result,CancellationToken ct){job.Status=result.Status;job.Error=result.Error;job.ProviderId=result.ProviderId;job.LeaseUntil=null;if(result.Retryable){job.Status=job.Attempts>=5?"DeadLetter":"Retry";job.NextAttemptAt=DateTimeOffset.UtcNow.AddSeconds(Math.Min(3600,Math.Pow(2,job.Attempts)*2));}if(result.Status is "Accepted" or "Delivered" or "Pickup")job.SentAt=DateTimeOffset.UtcNow;if(result.Status=="Delivered")job.DeliveredAt=DateTimeOffset.UtcNow;if(job.TenantId!=null&&job.Attempts>0)db.Add(new DeliveryAttempt{TenantId=job.TenantId.Value,OutboxId=job.Id,Number=job.Attempts,Status=job.Status,Code=result.Error??"",ProviderId=result.ProviderId??"",Cost=result.Cost,Currency=result.Currency});if(job.MessageId!=null){var m=await db.Set<CommunicationMessage>().FindAsync([job.MessageId],ct);if(m!=null)m.Status=job.Status;}if(job.IdempotencyKey?.StartsWith("event-invitation:")==true&&Guid.TryParse(job.IdempotencyKey[17..],out var invitationId)){var invitation=await db.Set<EventInvitation>().FindAsync([invitationId],ct);if(invitation!=null&&invitation.RespondedAt==null)invitation.Status=job.Status;}await db.SaveChangesAsync(ct);}
 async Task SystemNotifications(AppDb db,CancellationToken ct){foreach(var campaign in await db.Set<CommunicationCampaign>().AsNoTracking().Where(c=>c.Status=="Pending Approval").OrderByDescending(c=>c.CreatedAt).Take(100).ToListAsync(ct)){var stages=CommunityService.Stages(campaign.Stages);if(campaign.Stage>=stages.Length)continue;var permission=stages[campaign.Stage];var users=await db.Assignments.Where(x=>x.TenantId==campaign.TenantId&&x.UserId!=campaign.AuthorId&&x.RevokedAt==null&&x.StartsAt<=DateTimeOffset.UtcNow&&(x.EndsAt==null||x.EndsAt>DateTimeOffset.UtcNow)&&db.GovernanceRoles.Any(r=>r.Id==x.RoleId&&r.Permissions.Contains(permission))).Select(x=>x.UserId).Distinct().Take(500).ToListAsync(ct);foreach(var user in users){var key="review:"+campaign.Id+":"+campaign.Revision+":"+user;if(!await db.Set<CommunicationNotification>().AnyAsync(n=>n.TenantId==campaign.TenantId&&n.DedupKey==key,ct)&&!await db.Set<CommunicationPreference>().AnyAsync(p=>p.TenantId==campaign.TenantId&&p.UserId==user&&!p.InApp,ct)&&await Authority(db,campaign.TenantId,user,campaign.UnitId,permission))db.Add(new CommunicationNotification{TenantId=campaign.TenantId,UserId=user,Title="Review requested: "+campaign.Name,Kind="Approval",Link="/app/communications/review",ResourceId=campaign.Id,DedupKey=key});}}
var recent=await db.Audits.Where(a=>new[]{"membership.application.created","membership.created","event.invitations.created","event.registration.created","officer.appointment.decided"}.Contains(a.Action)&&db.Links.Any(l=>l.TenantId==a.TenantId&&l.UserId==a.ActorId)&&!db.Set<CommunicationNotification>().Any(n=>n.TenantId==a.TenantId&&n.UserId==a.ActorId&&n.DedupKey=="audit:"+a.Id)&&!db.Set<CommunicationPreference>().Any(p=>p.TenantId==a.TenantId&&p.UserId==a.ActorId&&!p.InApp)).OrderBy(a=>a.At).Take(50).ToListAsync(ct);foreach(var audit in recent){var user=audit.ActorId;if(user==Guid.Empty||!await db.Links.AnyAsync(l=>l.TenantId==audit.TenantId&&l.UserId==user,ct)||await db.Set<CommunicationNotification>().AnyAsync(n=>n.TenantId==audit.TenantId&&n.UserId==user&&n.DedupKey=="audit:"+audit.Id,ct))continue;if(await db.Set<CommunicationPreference>().AnyAsync(p=>p.TenantId==audit.TenantId&&p.UserId==user&&!p.InApp,ct))continue;db.Add(new CommunicationNotification{TenantId=audit.TenantId,UserId=user,Kind="System",Title=audit.Action.Replace('.',' '),Link=audit.Action.StartsWith("event")?"/app/community/events":"/app/members/self",ResourceId=audit.ResourceId,DedupKey="audit:"+audit.Id});}await db.SaveChangesAsync(ct);}
 async Task AutomationBatch(AppDb db,CancellationToken ct){await CommunicationAutomationRunner.Run(db,ct,config);}
}
